function* fib() {                      // unbounded, lazy, single-use
  let [a, b] = [0n, 1n];
  while (true) { yield a; [a, b] = [b, a + b]; }
}

for (const n of fib()) {               // pulls one element per iteration
  if (n > 1000n) break;                // stopping stops production
}

